insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000200061', '40000000-0000-4000-8000-000000020006', 'Na composição indicada, a função mais próxima da entrada é aplicada primeiro.', 1), ('60000000-0000-4000-8000-000000200062', '40000000-0000-4000-8000-000000020006', 'Comece encontrando $g(3)$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000020006', '$21$', 'A notação de composição define uma ordem: primeiro avaliamos a função interna e depois entregamos sua saída à função externa. Trocar essa ordem é um erro comum, porque em geral as duas funções não comutam.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000200061', '40000000-0000-4000-8000-000000020006', 'Aplique a função interna', '$g(3)=3^2+1=10$.', 1), ('70000000-0000-4000-8000-000000200062', '40000000-0000-4000-8000-000000020006', 'Use esse resultado em $f$', '$f(10)=2\cdot10+1$.', 2), ('70000000-0000-4000-8000-000000200063', '40000000-0000-4000-8000-000000020006', 'Conclua', '$(f\circ g)(3)=21$.', 3)
