insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000020009', '$7$', 'A notação de composição define uma ordem: primeiro avaliamos a função interna e depois entregamos sua saída à função externa. Trocar essa ordem é um erro comum, porque em geral as duas funções não comutam.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000200091', '40000000-0000-4000-8000-000000020009', 'Aplique a função interna', '$g(1)=1^2+1=2$.', 1), ('70000000-0000-4000-8000-000000200092', '40000000-0000-4000-8000-000000020009', 'Use esse resultado em $f$', '$f(2)=5\cdot2-3$.', 2), ('70000000-0000-4000-8000-000000200093', '40000000-0000-4000-8000-000000020009', 'Conclua', '$(f\circ g)(1)=7$.', 3)
