insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000200351', '40000000-0000-4000-8000-000000020035', 'Há uma função externa, a potência, e uma função interna linear.', 1), ('60000000-0000-4000-8000-000000200352', '40000000-0000-4000-8000-000000020035', 'Depois de derivar a potência, multiplique pela derivada da parte interna.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000020035', '$12(2x+4)^5$', 'A regra da cadeia mede duas variações: a da potência externa e a da expressão interna. O fator da derivada interna é indispensável, mesmo quando a expressão interna parece simples.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000200351', '40000000-0000-4000-8000-000000020035', 'Derive a camada externa', 'A derivada de $u^6$ é $6u^5$.', 1), ('70000000-0000-4000-8000-000000200352', '40000000-0000-4000-8000-000000020035', 'Reponha a expressão', 'Isso produz $6(2x+4)^5$.', 2), ('70000000-0000-4000-8000-000000200353', '40000000-0000-4000-8000-000000020035', 'Aplique a cadeia', 'Como $(2x+4)^{\\prime}=2$, resulta $12(2x+4)^5$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000020036', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000005', 'multiple_choice', 'medium', 'published', 'Se $x^2+y^2=9$, qual é $dy/dx$?')
