insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000200431', '40000000-0000-4000-8000-000000020043', 'Encontre o ponto', '$f(3)=9$, então o ponto é $(3,9)$.', 1), ('70000000-0000-4000-8000-000000200432', '40000000-0000-4000-8000-000000020043', 'Encontre a inclinação', '$f^{\\prime}(x)=2x$ e $f^{\\prime}(3)=6$.', 2), ('70000000-0000-4000-8000-000000200433', '40000000-0000-4000-8000-000000020043', 'Monte a reta', '$y-9=6(x-3)$, isto é, $y=6x-9$.', 3)
